// Brute force 5 middle bytes (36^5 = 60M)
#include <stdio.h>
#include <string.h>
#include <stdint.h>

static uint32_t crc32_table[256];

void init_crc32_table() {
    for (uint32_t i = 0; i < 256; i++) {
        uint32_t c = i;
        for (int j = 0; j < 8; j++) {
            c = (c >> 1) ^ (0xedb88320 * (c & 1));
        }
        crc32_table[i] = c;
    }
}

uint32_t crc32(const uint8_t *data, int len) {
    uint32_t crc = 0xffffffff;
    for (int i = 0; i < len; i++) {
        crc = crc32_table[(crc ^ data[i]) & 0xff] ^ (crc >> 8);
    }
    return crc ^ 0xffffffff;
}

uint32_t crc32_update(uint32_t crc, uint8_t b) {
    return crc32_table[(crc ^ b) & 0xff] ^ (crc >> 8);
}

int main() {
    init_crc32_table();
    uint8_t base[] = "PASSWORD=8XDP5Q2RT9Z";
    int base_len = 20;
    uint8_t suffix[] = "W54\n";
    int suffix_len = 4;
    uint32_t target = 0xb0725dc4;
    char charset[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    int cs = 36;
    uint8_t trial[33];

    memcpy(trial, base, base_len);
    memcpy(trial + base_len + 9, suffix, suffix_len);

    uint64_t count = 0;
    for (int i0 = 0; i0 < cs; i0++) {
        for (int i1 = 0; i1 < cs; i1++) {
            for (int i2 = 0; i2 < cs; i2++) {
                for (int i3 = 0; i3 < cs; i3++) {
                    for (int i4 = 0; i4 < cs; i4++) {
                        trial[20] = charset[i0];
                        trial[21] = charset[i1];
                        trial[22] = charset[i2];
                        trial[23] = charset[i3];
                        trial[24] = charset[i4];
                        uint32_t c = crc32(trial, 33);
                        if (c == target) {
                            trial[33] = 0; // not really, just for printing
                            printf("FOUND: %s\n", trial);
                            fflush(stdout);
                        }
                        count++;
                    }
                }
            }
            if (count % 1000000 == 0) {
                fprintf(stderr, "Progress: %lu\n", count);
            }
        }
    }
    fprintf(stderr, "Total: %lu\n", count);
    return 0;
}

// Brute force 9 middle bytes (36^9 = 10^14) - too slow for brute force
// Use meet-in-the-middle on CRC32
// Split into 5 bytes (forward) + 4 bytes (backward)
// Forward: compute state after 5 bytes for each of 36^5 = 60M
// Backward: for each of 36^4 = 1.7M, compute inverse to find required state before
// Look up in hash table
#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include <stdlib.h>

static uint32_t crc32_table[256];
static uint32_t crc32_table_rev[256];

void init_crc32_table() {
    for (uint32_t i = 0; i < 256; i++) {
        uint32_t c = i;
        for (int j = 0; j < 8; j++) {
            c = (c >> 1) ^ (0xedb88320 * (c & 1));
        }
        crc32_table[i] = c;
    }
}

// Compute inverse CRC: given state after processing bytes, find state before
// For each bit position in input, we can reverse
// CRC32 is essentially: state = (state >> 8) ^ table[(state ^ b) & 0xff]
// Inverse: given state_out and byte b, find state_in
// state_in = (state_out ^ table[(state_in ^ b) & 0xff]) << 8 ... no this is wrong
// Actually, state_out = table[(state_in ^ b) & 0xff] ^ (state_in >> 8)
// So state_in = (state_out ^ table[(state_in ^ b) & 0xff]) << 8 | ((state_in ^ b) & 0xff)
// Hmm, need to think more carefully

// Let me use a different approach: simulate the inverse
// state_in = (state_in >> 8) ^ table[(state_in ^ b) & 0xff] doesn't quite work
// Let's use: state_out = table[(state_in ^ b) & 0xff] ^ (state_in >> 8)
// So state_in's low byte is b ^ (state_in's low byte) ... circular

// Better: state_in = (state_out ^ lookup) << 8 | index, where index = (state_in ^ b) & 0xff
// So state_in = ((state_out ^ table[index]) << 8) | index
// And index = (state_in ^ b) & 0xff
// So state_in's low byte = index, state_in's high 24 bits = (state_out ^ table[index]) << 8 (shifted)
